function HotelServices() {
  const fadeIn = {
    initial: { opacity: 0, y: 20 },
    animate: { opacity: 1, y: 0 },
    transition: { duration: 0.6 },
  };

  const staggerChildren = {
    animate: {
      transition: {
        staggerChildren: 0.2,
      },
    },
  };

  return (
    <section className="max-w-7xl mx-auto px-4 sm:px-7 lg:px-8 py-16 lg:py-24">
      <div className="grid lg:grid-cols-2 gap-12 lg:gap-16 items-center">
        {/* Left Section */}
        <motion.div
          className="text-center lg:text-left"
          initial="initial"
          animate="animate"
          variants={fadeIn}
        >
          <div className="flex items-center justify-center lg:justify-start space-x-4">
            <p className="uppercase text-[#AE7D54] tracking-[0.2em] font-['Playfair_Display']">
              Experience Hoteler
            </p>
            <img src={design} alt="Design" className="p-1" />
          </div>

          <h2 className="text-3xl lg:text-4xl xl:text-5xl font-['Playfair_Display'] text-black mt-6 leading-tight">
            Making Every Stay <br /> Effortless and Enjoyable
          </h2>

          <p className="text-gray-600 text-lg mt-6 max-w-xl mx-auto lg:mx-0">
            We understand that it’s the little things that create big memories.{" "}
            <br />
            That’s why our services are thoughtfully designed to provide <br />{" "}
            maximum comfort and convenience.
          </p>
        </motion.div>

        {/* Right Section */}
        <motion.div
          className="space-y-8"
          variants={staggerChildren}
          initial="initial"
          animate="animate"
        >
          {highlights.map((item, index) => (
            <motion.div
              key={index}
              className="flex items-center justify-between border-t border-[#F7F3EE] pt-8 group"
              variants={fadeIn}
              whileHover={{ x: 10 }}
              transition={{ type: "spring", stiffness: 300 }}
            >
              <div className="flex items-center space-x-6">
                <span className="text-7xl lg:text-8xl font-['Playfair_Display'] text-gray-200 transition-colors group-hover:text-gray-300">
                  {item.number}
                </span>
                <div className="transform transition-transform group-hover:scale-110">
                  {item.icon}
                </div>
              </div>
              <div className="text-right">
                <h3 className="text-xl lg:text-2xl font-['Playfair_Display'] text-black mb-2">
                  {item.title}
                </h3>
                <button className="inline-flex flex-col items-end group cursor-pointer">
                  <span className="text-gray-500 text-sm uppercase tracking-wider mb-2 group-hover:text-[#AE7D54] transition-colors">
                    Read More
                  </span>
                  <span className="block w-12 h-0.5 bg-[#AE7D54] transform origin-right transition-all duration-300 group-hover:w-24" />
                </button>
              </div>
            </motion.div>
          ))}
        </motion.div>
      </div>
    </section>
  );
}

export default HotelServices;
